using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public sealed class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    #region AddStock and GetStockLevel

    [TestMethod]
    public void AddStock_SingleItem_IncreasesStockLevel()
    {
        _tracker.AddStock("SKU-001", 10);

        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    public void AddStock_MultipleTimes_AccumulatesQuantity()
    {
        _tracker.AddStock("SKU-001", 5);
        _tracker.AddStock("SKU-001", 3);

        Assert.AreEqual(8, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    public void AddStock_DifferentWarehouses_TrackedSeparately()
    {
        _tracker.AddStock("SKU-001", 10, "warehouse-A");
        _tracker.AddStock("SKU-001", 7, "warehouse-B");

        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-001", "warehouse-A"));
        Assert.AreEqual(7, _tracker.GetStockLevel("SKU-001", "warehouse-B"));
    }

    [TestMethod]
    public void GetStockLevel_TotalAcrossWarehouses()
    {
        _tracker.AddStock("SKU-001", 10, "warehouse-A");
        _tracker.AddStock("SKU-001", 5, "warehouse-B");

        Assert.AreEqual(15, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN"));
    }

    [TestMethod]
    public void AddStock_NullSku_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _tracker.AddStock(null!, 5));
    }

    [TestMethod]
    public void AddStock_ZeroQuantity_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _tracker.AddStock("SKU-001", 0));
    }

    [TestMethod]
    public void AddStock_NegativeQuantity_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _tracker.AddStock("SKU-001", -1));
    }

    #endregion

    #region RemoveStock

    [TestMethod]
    public void RemoveStock_DecreasesStockLevel()
    {
        _tracker.AddStock("SKU-001", 10);
        _tracker.RemoveStock("SKU-001", 3);

        Assert.AreEqual(7, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    public void RemoveStock_AllStock_LeavesZero()
    {
        _tracker.AddStock("SKU-001", 5);
        _tracker.RemoveStock("SKU-001", 5);

        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    public void RemoveStock_InsufficientStock_Throws()
    {
        _tracker.AddStock("SKU-001", 3);

        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-001", 5));
        Assert.Contains("Insufficient stock", ex.Message);
    }

    [TestMethod]
    public void RemoveStock_NegativeQuantity_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _tracker.RemoveStock("SKU-001", -1));
    }

    #endregion

    #region NeedsReorder

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.SetReorderThreshold("SKU-001", 10);
        _tracker.AddStock("SKU-001", 5);

        Assert.IsTrue(_tracker.NeedsReorder("SKU-001"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtThreshold_ReturnsTrue()
    {
        _tracker.SetReorderThreshold("SKU-001", 10);
        _tracker.AddStock("SKU-001", 10);

        Assert.IsTrue(_tracker.NeedsReorder("SKU-001"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.SetReorderThreshold("SKU-001", 10);
        _tracker.AddStock("SKU-001", 15);

